{"implementation": "def solve(case):
    edges = case["edges"]
    refinement = case["refinement"]
    from collections import defaultdict
    weight_map = defaultdict(int)
    node_to_comm = refinement
    for u, v, w in edges:
        cu = node_to_comm[u]
        cv = node_to_comm[v]
        if cu > cv:
            cu, cv = cv, cu
        weight_map[(cu, cv)] += w
    aggregate_edges = sorted([list(k) + [v] for k, v in weight_map.items()])
    members = defaultdict(list)
    for node, comm in node_to_comm.items():
        members[comm].append(node)
    for comm in members:
        members[comm].sort()
    return {"aggregate_edges": aggregate_edges, "members": dict(members)}
"}
